import sqlite3
from datetime import datetime

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("reservations")
DB_PATH = "reservations.db"


@mcp.tool()
def find_available_tables(restaurant_id: int, date: str, time: str, party_size: int) -> dict:
    if restaurant_id <= 0:
        return {"error": "restaurant_id must be positive"}
    if party_size < 1 or party_size > 20:
        return {"error": "party_size must be between 1 and 20"}
    try:
        start = datetime.strptime(f"{date} {time}", "%Y-%m-%d %H:%M")
    except ValueError:
        return {"error": "date must be YYYY-MM-DD and time must be HH:MM"}
    if start < datetime.now():
        return {"error": "requested time is in the past"}

    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    rows = conn.execute(
        "SELECT t.id, t.label, t.capacity FROM tables t "
        "WHERE t.restaurant_id = ? AND t.capacity >= ? AND t.id NOT IN ("
        "SELECT table_id FROM reservations WHERE restaurant_id = ? "
        "AND status = 'confirmed' AND start_time < datetime(?, '+90 minutes') "
        "AND datetime(start_time, '+90 minutes') > ?) ORDER BY t.capacity",
        (restaurant_id, party_size, restaurant_id, start.isoformat(" "), start.isoformat(" ")),
    ).fetchall()
    conn.close()
    return {"available": [dict(r) for r in rows], "count": len(rows)}

import sqlite3
from contextlib import closing

from agents import function_tool as tool

DB_PATH = "reservations.db"


@tool
def cancel_reservation(reservation_id: int, guest_phone: str) -> dict:
    if reservation_id <= 0:
        return {"ok": False, "error": "invalid reservation_id"}
    phone = "".join(ch for ch in guest_phone if ch.isdigit())
    if len(phone) < 7:
        return {"ok": False, "error": "invalid phone number"}

    with closing(sqlite3.connect(DB_PATH)) as conn:
        conn.row_factory = sqlite3.Row
        with conn:
            row = conn.execute(
                "SELECT id, restaurant_id, table_id, guest_name, guest_phone, "
                "party_size, start_time, status FROM reservations WHERE id = ?",
                (reservation_id,),
            ).fetchone()
            if row is None:
                return {"ok": False, "error": "reservation not found"}
            stored = "".join(ch for ch in row["guest_phone"] if ch.isdigit())
            if stored[-7:] != phone[-7:]:
                return {"ok": False, "error": "phone number does not match"}
            conn.execute("DELETE FROM reservations WHERE id = ?", (reservation_id,))
            return {"ok": True, "cancelled": dict(row)}

from dataclasses import dataclass
from typing import Optional

import stripe
from agents import function_tool as tool

FEE_PER_GUEST_CENTS = 1500


@dataclass
class ChargeResult:
    success: bool
    charge_id: Optional[str]
    amount_cents: int
    message: str


@tool
def charge_no_show_fee(reservation_id: int, customer_id: str, party_size: int) -> ChargeResult:
    amount = FEE_PER_GUEST_CENTS * max(party_size, 0)
    if amount == 0:
        return ChargeResult(False, None, 0, "party_size must be at least 1")
    try:
        intent = stripe.PaymentIntent.create(
            amount=amount,
            currency="usd",
            customer=customer_id,
            off_session=True,
            confirm=True,
            description=f"No-show fee for reservation {reservation_id}",
            metadata={"reservation_id": str(reservation_id)},
            idempotency_key=f"no-show-{reservation_id}",
        )
    except stripe.error.StripeError as exc:
        return ChargeResult(False, None, amount, str(exc))
    return ChargeResult(intent.status == "succeeded", intent.id, amount, intent.status)

import stripe
from agents import function_tool as tool


@tool
def refund_reservation_deposit(payment_intent_id: str, amount_cents: int = 0, reason: str = "requested_by_customer") -> dict:
    result = {"payment_intent_id": payment_intent_id, "refunded": False}
    if not payment_intent_id.startswith("pi_"):
        result["error"] = "invalid payment intent id"
        return result
    if reason not in ("requested_by_customer", "duplicate", "fraudulent"):
        reason = "requested_by_customer"
    params = {"payment_intent": payment_intent_id, "reason": reason}
    if amount_cents and amount_cents > 0:
        params["amount"] = amount_cents
    try:
        refund = stripe.Refund.create(**params)
    except stripe.error.StripeError as exc:
        result["error"] = str(exc)
        return result
    result.update(
        {
            "refunded": refund.status in ("succeeded", "pending"),
            "refund_id": refund.id,
            "amount_cents": refund.amount,
            "status": refund.status,
            "currency": refund.currency,
        }
    )
    return result
